1	use codex_protocol::config_types::CollaborationModeMask;
2	use codex_protocol::config_types::ModeKind;
3	
4	use crate::model_catalog::ModelCatalog;
5	
6	fn filtered_presets(model_catalog: &ModelCatalog) -> Vec<CollaborationModeMask> {
7	    model_catalog
8	        .list_collaboration_modes()
9	        .into_iter()
10	        .filter(|mask| mask.mode.is_some_and(ModeKind::is_tui_visible))
11	        .collect()
12	}
13	
14	pub(crate) fn presets_for_tui(model_catalog: &ModelCatalog) -> Vec<CollaborationModeMask> {
15	    filtered_presets(model_catalog)
16	}
17	
18	pub(crate) fn default_mask(model_catalog: &ModelCatalog) -> Option<CollaborationModeMask> {
19	    let presets = filtered_presets(model_catalog);
20	    presets
21	        .iter()
22	        .find(|mask| mask.mode == Some(ModeKind::Default))
23	        .cloned()
24	        .or_else(|| presets.into_iter().next())
25	}
26	
27	pub(crate) fn mask_for_kind(
28	    model_catalog: &ModelCatalog,
29	    kind: ModeKind,
30	) -> Option<CollaborationModeMask> {
31	    if !kind.is_tui_visible() {
32	        return None;
33	    }
34	    filtered_presets(model_catalog)
35	        .into_iter()
36	        .find(|mask| mask.mode == Some(kind))
37	}
38	
39	/// Cycle to the next collaboration mode preset in list order.
40	pub(crate) fn next_mask(
41	    model_catalog: &ModelCatalog,
42	    current: Option<&CollaborationModeMask>,
43	) -> Option<CollaborationModeMask> {
44	    let presets = filtered_presets(model_catalog);
45	    if presets.is_empty() {
46	        return None;
47	    }
48	    let current_kind = current.and_then(|mask| mask.mode);
49	    let next_index = presets
50	        .iter()
51	        .position(|mask| mask.mode == current_kind)
52	        .map_or(0, |idx| (idx + 1) % presets.len());
53	    presets.get(next_index).cloned()
54	}
55	
56	pub(crate) fn default_mode_mask(model_catalog: &ModelCatalog) -> Option<CollaborationModeMask> {
57	    mask_for_kind(model_catalog, ModeKind::Default)
58	}
59	
60	pub(crate) fn plan_mask(model_catalog: &ModelCatalog) -> Option<CollaborationModeMask> {
61	    mask_for_kind(model_catalog, ModeKind::Plan)
62	}
