pub(crate) fn set_model(&mut self, model: impl Into<String>) {
        let model = model.into();
        self.current_collaboration_mode = self.current_collaboration_mode.with_updates(
            Some(model.clone()),
            /*effort*/ None,
            /*developer_instructions*/ None,
        );
        if self.collaboration_modes_enabled()
            && let Some(mask) = self.active_collaboration_mask.as_mut()
        {
            mask.model = Some(model.clone());
        }
        self.refresh_model_display();
        // Keep the terminal title in sync with the newly selected model so a
        // `model`-tokened title updates immediately without a separate refresh.
        self.refresh_terminal_title();
    }

